{
        int err = 0;
        long timeout = *timeo_p;
        int result = 0;

        atomic_inc(&asoc->refcnt);

        while (1) {
                if (msg_len <= asoc->sndbuf_used) {
                        result = 0;
                        break;
                }

                if (!timeout) {
                        result = -EAGAIN;
                        break;
                }

                if (signal_pending(current)) {
                        result = -ERESTARTSYS;
                        break;
                }

                if (asoc->state == SCTP_STATE_CLOSED) {
                        result = -EPIPE;
                        break;
                }

                if (timeout > HZ)
                        schedule_timeout_interruptible(HZ);
                else
                        schedule_timeout_interruptible(timeout);
                timeout -= HZ;
