int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    int ret = 0;
    long timeout;
    long left;

    sctp_association_hold(asoc);

    for (;;) {
        if (msg_len <= asoc->sndbuf_used)
            break;

        timeout = *timeo_p;
        if (timeout == 0) {
            ret = -EAGAIN;
            break;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            break;
        }

        left = schedule_timeout(timeout);
        *timeo_p = left;

        if (*timeo_p <= 0) {
            ret = -ETIMEDOUT;
            break;
        }

        if (asoc->state == SCTP_STATE_ABORTEDPENDING ||
            asoc->state == SCTP_STATE_CLOSED ||
            asoc->state == SCTP_STATE_SHUTDOWN_PENDING) {
            ret = -EPIPE;
            break;
        }
    }

    sctp_association_put(asoc);
    return ret;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    long timeout;
    int err = 0;
    int need_wait = 1;

    sctp_association_hold(asoc);

    while (need_wait) {
        if (msg_len <= asoc->sndbuf_used) {
            need_wait = 0;
            break;
        }

        if (*timeo_p < 0)
            return -EAGAIN;

        timeout = *timeo_p;
        err = wait_event_interruptible_timeout(sctp_wait_event,
                                               (msg_len <= asoc->sndbuf_used),
                                               timeout);
        if (err <= 0) {
            if (signal_pending(current))
                err = -ERESTARTSYS;
            else if (!err)
                err = -ETIMEDOUT;
            break;
        }

        if (!asoc->active || asoc->state != SCTP_ACTIVE) {
            err = -EPIPE;
            break;
        }

        *timeo_p = timeout;
    }

    sctp_association_put(asoc);

    if (err)
        return err;

    return 0;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    long timeout;
    int error = 0;
    int result = 0;
    int noblock = 0;

    /* Increment reference count on the association */
    sctp_association_hold(asoc);

    timeout = *timeo_p;

    while (1) {
        if (signal_pending(current)) {
            error = -EINTR;
            break;
        }

        if (noblock) {
            result = -EAGAIN;
            break;
        }

        if (msg_len <= asoc->sndbuf_used) {
            result = 0;
            break;
        }

        if (!timeout) {
            result = -ETIMEDOUT;
            break;
        }

        /* Prepare to wait for send buffer space */
        error = wait_event_interruptible_timeout(asoc->wait,
                                                 (msg_len <= asoc->sndbuf_available),
                                                 timeout);
        if (error <= 0) {
            if (error == -ERESTARTSYS) {
                error = -EINTR;
            } else if (!error) {
                error = -ETIMEDOUT;
            }
            break;
        }

        timeout = error;
    }

    /* Decrement reference count on the association */
    sctp_association_put(asoc);

    if (error) {
        if (error == -EINTR) {
            result = -EINTR;
        } else if (error == -ETIMEDOUT) {
            result = -ETIMEDOUT;
        } else if (error == -EPIPE) {
            result = -EPIPE;
        } else {
            result = -EAGAIN;
        }
    }

    *timeo_p = timeout;
    return result;
}

int sctp_wait_for_sndbuf(struct sctp_association *asoc, long *timeo_p, size_t msg_len)
{
    long timeout;
    int ret = 0;
    int wait_result = 0;

    SCTP_INC_REF(asoc);

    while (1) {
        if (msg_len <= asoc->autils->free) {
            break;
        }

        timeout = *timeo_p;
        if (timeout == 0) {
            ret = -EAGAIN;
            goto out;
        }

        if (signal_pending(current)) {
            ret = -EINTR;
            goto out;
        }

        if (!asoc->active) {
            ret = -ENOTCONN;
            goto out;
        }

        wait_result = wait_event_interruptible_timeout(asoc->wait,
                                                      (msg_len <= asoc->autils->free),
                                                      timeout);
        if (wait_result <= 0) {
            if (wait_result == 0)
                ret = -ETIMEDOUT;
            else if (wait_result == -ERESTARTSYS)
                ret = -EINTR;
            goto out;
        }
    }

out:
    SCTP_DEC_REF(asoc);
    return ret;
}
